				t.Errorf("redhatBase.parseInstalledPackagesLine() gotsp = %v, wantsp %v", gotsp, tt.wantsp)
			}
			if tt.wantWarning == "" {
				if len(o.warns) != 0 {
					t.Errorf("redhatBase.parseInstalledPackagesLine() warnings = %v, want none", o.warns)
