			} else if len(o.warns) != 1 || !strings.Contains(o.warns[0].Error(), tt.wantWarning) {
				t.Errorf("redhatBase.parseInstalledPackagesLine() warnings = %v, want one containing %q", o.warns, tt.wantWarning)
			}
		})
	}
